      "rank": 1,
      "ballot_id": "B001",
      "proposed_laureates": ["Hidetoshi Katori", "Jun Ye"],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks turn precision timekeeping into a powerful test of fundamental physics, with broad scientific reach and extraordinary measurement performance.",
        "attribution": "Katori and Ye developed complementary approaches that established the field; the proposed credit is focused and credible.",
        "maturity": "The technique is established, repeatedly demonstrated, and continues to improve.",
        "uncertainties": ["The boundary between the original clock concepts and the wider community's later advances would need careful review."]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B049",
      "proposed_laureates": ["Michel Della Negra", "Peter Jenni", "Tejinder S. Virdee"],
      "assessment": {
        "nobel_worthiness": "The experimental discovery of the Higgs boson completed a central prediction of particle physics and opened a new domain for precision tests.",
        "attribution": "These leaders played major roles in building and guiding the ATLAS and CMS experiments, though the discovery depended on very large collaborations.",
        "maturity": "The signal was independently established by two experiments and subsequent measurements have confirmed the particle's properties.",
        "uncertainties": ["Recognizing a few individuals for work by thousands of collaborators requires a defensible contribution-based rationale."]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B022",
      "proposed_laureates": ["Francis Halzen"],
      "assessment": {
        "nobel_worthiness": "Detecting high-energy astrophysical neutrinos established a new way to observe the distant universe and connect particle physics with astrophysics.",
        "attribution": "Halzen was a leading architect and scientific advocate of IceCube; the discovery itself was collective and should be distinguished from his leadership.",
        "maturity": "The astrophysical flux has been supported by accumulating events and independent analyses, making this a durable observational result.",
        "uncertainties": ["The precise division between detector leadership, the first detection, and later source identifications merits expert review."]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B003",
      "proposed_laureates": ["Alexandre Blais", "Andreas Wallraff", "Robert J. Schoelkopf"],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics made controlled interactions between light and matter possible in an engineered quantum system and became a foundation for superconducting quantum technologies.",
        "attribution": "Blais supplied key theoretical architecture, while Wallraff and Schoelkopf helped establish the experimental platform; their roles are complementary.",
        "maturity": "The basic physics has been reproduced and extended across many laboratories, with a substantial record of experimental control.",
        "uncertainties": ["The prize scope should separate the original cQED achievement from later advances in quantum computing."]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B008",
      "proposed_laureates": ["Alexei Kitaev", "Andrew M. Steane", "Peter W. Shor"],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed that fragile quantum information can in principle be protected, transforming quantum computation from an idealized proposal into a physically meaningful program.",
        "attribution": "Shor and Steane introduced landmark codes and Kitaev developed influential topological approaches; the credit reflects distinct foundational contributions.",
        "maturity": "The principles are firmly established and experimental logical qubits now demonstrate correction, although large-scale fault tolerance remains a work in progress.",
        "uncertainties": ["The committee would need to define whether the recognized discovery is the first codes, the general fault-tolerance framework, or topological protection."]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B046",
      "proposed_laureates": ["Immanuel Bloch", "Markus Greiner", "Peter Zoller"],
      "assessment": {
        "nobel_worthiness": "Optical lattices made it possible to prepare and probe controlled many-body quantum systems, including regimes that are difficult to access in ordinary materials.",
        "attribution": "Zoller helped establish the theoretical program, while Bloch and Greiner led seminal experimental demonstrations; the field's progress is highly collective.",
        "maturity": "The platform is mature and reproducible, with increasingly capable quantum simulation experiments.",
        "uncertainties": ["There is overlap with atomic quantum computation and simulation more generally, so a precise discovery boundary is needed."]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B007",
      "proposed_laureates": ["Charles L. Kane", "Laurens W. Molenkamp"],
      "assessment": {
        "nobel_worthiness": "The prediction and observation of quantum spin Hall states and topological insulators revealed a new class of electronic phases with protected boundary behavior.",
        "attribution": "Kane's theoretical work and Molenkamp's experimental demonstrations form a compelling theory-experiment pairing, though other foundational contributors also warrant scrutiny.",
        "maturity": "The phases have been observed and studied in multiple material systems, and the topological framework is well established.",
        "uncertainties": ["The long and overlapping history of topological matter makes a fair, narrowly defined attribution essential."]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B021",
      "proposed_laureates": ["Edward Witten", "Juan Maldacena"],
      "assessment": {
        "nobel_worthiness": "Gauge/gravity duality is a profound conceptual development that has reshaped work on quantum gravity, strongly coupled field theories, and black holes.",
        "attribution": "Witten supplied important foundations and Maldacena formulated the duality in its influential form; the proposed pair captures central contributions without implying sole authorship.",
        "maturity": "The mathematical framework has been developed extensively and applied successfully in theory, but direct evidence that nature realizes the duality is lacking.",
        "uncertainties": ["Its striking explanatory power remains largely within theoretical physics, and the connection to experimentally tested fundamental physics is indirect."]
      }
    }
  ]
}
